```groovy
import com.atlassian.jira.issue.Issue;
import com.atlassian.jira.issue.IssueField;
import com.atlassian.jira.issue.fields.checklist.ChecklistField;
import com.atlassian.jira.workflow.Workflow;
import com.atlassian.jira.workflow.WorkflowException;

public class ChecklistCompletionValidation implements WorkflowValidation {
    public void validate(Issue issue, Workflow workflow) throws WorkflowException {
        ChecklistField checklistField = (ChecklistField) issue.getField("Checklist");
        List<String> checklistItems = checklistField.getValues();

        // Check if all checklist items are completed
        boolean allItemsCompleted = true;
        for (String item : checklistItems) {
            if (!item.equals("Done")) {
                allItemsCompleted = false;
                break;
            }
        }

        if (!allItemsCompleted) {
            throw new WorkflowException("All checklist items must be completed before moving to the next column.");
        }
    }
}
```
