public static void CalculateTotalCost(out decimal carPrice, out decimal clothesPrice, out decimal bookPrice, out decimal totalCost)
{
    carPrice = 3000m;
    clothesPrice = 100m;
    bookPrice = 20m;

    var combinedClothesAndBookPrice = clothesPrice + bookPrice;
    var requiredCarPrice = combinedClothesAndBookPrice * 2;

    if (carPrice < requiredCarPrice)
    {
        var difference = requiredCarPrice - carPrice;
        carPrice += difference;
    }

    totalCost = carPrice + clothesPrice + bookPrice;
}
