Here's an example of how to retrieve a message and check if it has been read using the Slack API:
```javascript
const axios = require('axios');

async function getMessage(messageId) {
  try {
    const response = await axios.get(`https://slack.com/api/channels.history`, {
      params: {
        channel: '#your-channel',
        count: 1,
        message_ts: messageId,
      },
      headers: {
        'Authorization': `Bearer ${process.env.SLACK_API_KEY}`,
      },
    });

    const message = response.data.messages[0];
    return message;
  } catch (error) {
    console.error(error);
    return null;
  }
}

async function main() {
  const messageId = 'your-message-id';
  const message = await getMessage(messageId);

  if (message) {
    const read = message.read;
    console.log(`Message with ID ${messageId} has been read: ${read}`);
  } else {
    console.log(`Message with ID ${messageId} not found`);
  }
}

main();
```
Replace `#your-channel` with the channel where the message was sent and `your-message-id` with the actual message ID you want to check.

