Here's an example of a generic REST service wrapper class in C# that includes auth token handling:
```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json.Linq;
using System.Net.Http;
using System.Net.Http.Headers;

public class RestServiceWrapper<T>
{
    private readonly string _baseAddress;
    private readonly string _authToken;

    public RestServiceWrapper(string baseAddress, string authToken)
    {
        _baseAddress = baseAddress;
        _authToken = authToken;
    }

    public async Task<T> GetAsync()
    {
        using (var client = new HttpClient())
        {
            client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", _authToken);
            var response = await client.GetAsync(_baseAddress);
            if (response.IsSuccessStatusCode)
            {
                return await response.Content.ReadAsAsync<T>();
            }
            else
            {
                throw new Exception($"Failed to fetch data from {_baseAddress}: {response.StatusCode} - {response.ReasonPhrase}");
            }
        }
    }
}

public class MyRestService : RestServiceWrapper<MyData>
{
