Here's a Go program that parses a struct in a Go source file and generates an Avro schema from it:

```go
package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"log"
	"os"
	"strings"

	"github.com/apache/avro/v2/schema"
)

type StructDef struct {
	Name   string `json:"name"`
	Fields []Field `json:"fields"`
}

type Field struct {
	Name    string `json:"name"`
	Type    string `json:"type"`
	Default string `json:"default"`
}

func main() {
	if len(os.Args) != 3 {
		log.Fatal("Usage: ./parse_go_struct <go_source_file> <struct_name>")
	}

	goSourceFile := os.Args[1]
	structName := os.Args[2]

	content, err := ioutil.ReadFile(goSourceFile)
	if err != nil {
		log.Fatal(err)
	}

	var structDef StructDef
	err = json.Unmarshal(content, &structDef)
	if err != nil {
		log.Fatal(err)
	}

	schemaDef := schema.MakeSchema(structDef.Fields, nil)
	avroSchema, err := schemaDef.ToJSON()
	if err != nil {
		log.Fatal(err)
	}

	outputFile := fmt.Sprintf("%s.avsc", structName)
	err = ioutil.WriteFile(outputFile, []byte(avroSchema), 0644)
	if err != nil {
		log.Fatal(err)
	}

	fmt.Printf("Avro schema for %s generated successfully and written to %s\n", structName, outputFile)
}
```

To use this program, save it as `parse_go_struct.go`, make it executable with `chmod +x parse_go_struct.go`, and then run it with the name of the Go

