function my_widgets_layout() {
    register_widget('WP_Widget_Text');
    register_widget('WP_Widget_Calendar');
    register_widget('WP_Widget_Recent_Posts');
}
add_action('widgets_init', 'my_widgets_layout');

function my_widgets_area() {
